'use strict';
const assert = require('node:assert/strict');
const parser = require('../static/glucose-history.js');

function csv(...lines) { return lines.join('\r\n'); }
const uk = csv(
  'Glucose Data,Generated on,25-10-2026,Generated by,EXAMPLE',
  'Device,Serial Number,Device Timestamp,Record Type,Historic Glucose mmol/L,Scan Glucose mmol/L,Notes',
  'Libre,TEST,25/10/2026 18:30,0,6.1,,',
  'Libre,TEST,25/10/2026 18:15,0,6.3,,"quoted, ignored"',
  'Libre,TEST,25/10/2026 18:20,1,,6.8,',
  'Libre,TEST,25/10/2026 18:30,0,6.2,,'
);
const readings=parser.parseLibreViewCsv(uk,{dateOrder:'DMY'}).readings;
assert.equal(readings.length,2,'scan/duplicate filtering');
assert.deepEqual(readings.map(v=>v.mmol),[6.3,6.2],'time sort/dedup');
assert.equal(parser.historyWindow(readings,3).length,2);
assert.equal(parser.parseLocalTime('25/10/2026 18:30','DMY'), readings[1].timestamp);

const us = csv(
  'Glucose Data,Generated on,10/25/2026',
  'Device Timestamp,Record Type,Historic Glucose mg/dL',
  '10/25/2026 6:15 PM,0,108'
);
const mg=parser.parseLibreViewCsv(us,{dateOrder:'MDY'});
assert.equal(mg.convertedFromMgdl,true);
assert.ok(Math.abs(mg.readings[0].mmol - 5.994)<0.02,'mg/dL converted to mmol/L');
assert.equal(parser.parseLocalTime('2026-10-25 18:15','DMY'), readings[0].timestamp);

assert.throws(()=>parser.parseLibreViewCsv('Device Timestamp,Record Type\n25/10/2026 18:00,0'),/columns not found/);
assert.throws(()=>parser.parseLibreViewCsv('Device Timestamp,Record Type,Historic Glucose mmol\/L\n2026-10-25 18:00,1,6.2'),/No usable historic/);
assert.throws(()=>parser.parseLibreViewCsv('Device Timestamp,Record Type,Historic Glucose mmol\/L\n25\/10\/2026 18:00,0,80',{dateOrder:'DMY'}),/No usable historic/);
assert.equal(parser.parseLocalTime('31/02/2026 09:00','DMY'),null);
assert.equal(parser.parseLocalTime('13/10/2026 09:00','MDY'),null);
assert.throws(()=>parser.parseLibreViewCsv('"unfinished'),/columns not found|unfinished/);

// TSV CSV variants: still no network, no upload, no credential usage.
const tsv='Glucose Data\tGenerated on\nDevice Timestamp\tRecord Type\tHistoric Glucose (mmol/L)\n2026-10-25 10:00\t0\t4.5';
assert.equal(parser.parseLibreViewCsv(tsv,{dateOrder:'DMY'}).readings[0].mmol,4.5);
console.log('LibreView local parser: 12 assertions passed');
